from pathlib import Path
from collections import Counter, defaultdict
import h5py, numpy as np, scipy.io

root = Path('/app/data')
files = sorted(root.rglob('data_structure_*.mat'))

def summarize_non_hdf5(p):
    mat = scipy.io.loadmat(str(p), squeeze_me=True, struct_as_record=False)
    obj = mat['obj']
    ntrials = int(round(float(obj.bp.Ntrials)))
    has_clu = hasattr(obj, 'clu')
    n_neurons = 0
    probe_locs = []
    if has_clu:
        clu = obj.clu
        if not isinstance(clu, np.ndarray):
            clu = np.array([clu], dtype=object)
        exprobe = getattr(obj.ex, 'probe', None) if hasattr(obj, 'ex') else None
        if exprobe is None:
            exprobe = []
        elif not isinstance(exprobe, (list, np.ndarray)):
            exprobe = [exprobe]
        for idx, probe in enumerate(np.ravel(clu)):
            if probe is None:
                continue
            try:
                n = len(probe)
            except TypeError:
                n = 1
            n_neurons += n
            loc = None
            if idx < len(exprobe):
                loc = getattr(exprobe[idx], 'loc', None)
            probe_locs.append(loc)
    return ntrials, has_clu, n_neurons, probe_locs

def read_scalar(ds):
    arr = ds[()]
    if isinstance(arr, np.ndarray):
        return arr.reshape(-1)[0]
    return arr

def decode_maybe_char(f, item):
    if isinstance(item, h5py.Reference):
        if not item:
            return None
        obj = f[item]
        if not isinstance(obj, h5py.Dataset):
            return None
        arr = obj[()]
    else:
        arr = np.asarray(item)
    arr = np.asarray(arr)
    if arr.size == 0:
        return None
    flat = arr.reshape(-1)
    if flat.dtype.kind in ('u','i','f') and np.nanmax(flat) <= 255:
        try:
            return ''.join(chr(int(x)) for x in flat if int(x) != 0)
        except Exception:
            return None
    return None

def probe_locs_hdf5(f, obj_group):
    if 'ex' not in obj_group or 'probe' not in obj_group['ex']:
        return []
    ex_probe = obj_group['ex']['probe']
    locs = []
    if isinstance(ex_probe, h5py.Group):
        if 'loc' in ex_probe:
            locs.append(decode_maybe_char(f, ex_probe['loc'][()]))
    else:
        refs = ex_probe[()]
        for ref in refs.reshape(-1):
            if not ref:
                locs.append(None)
                continue
            node = f[ref]
            if isinstance(node, h5py.Group) and 'loc' in node:
                locs.append(decode_maybe_char(f, node['loc'][()]))
            else:
                locs.append(None)
    return locs

def summarize_hdf5(p):
    with h5py.File(p, 'r') as f:
        obj = f['obj']
        ntrials = int(round(float(read_scalar(obj['bp']['Ntrials']))))
        has_clu = 'clu' in obj
        n_neurons = 0
        probe_locs = []
        if has_clu:
            locs = probe_locs_hdf5(f, obj)
            clu_refs = obj['clu'][()]
            for pix, ref in enumerate(clu_refs.reshape(-1), start=1):
                if not ref:
                    continue
                node = f[ref]
                if isinstance(node, h5py.Dataset):
                    continue
                n = int(node['quality'].shape[0])
                n_neurons += n
                loc = locs[pix-1] if pix-1 < len(locs) else None
                probe_locs.append(loc)
        return ntrials, has_clu, n_neurons, probe_locs

summary = []
region_counts = Counter()
sessions_by_task = Counter()
subjects_by_task = defaultdict(set)
trials_by_task = Counter()
for p in files:
    parts = p.stem.split('_')
    folder, subj, date = p.parent.name, parts[2], parts[3]
    if h5py.is_hdf5(str(p)):
        ntrials, has_clu, n_neurons, locs = summarize_hdf5(p)
    else:
        ntrials, has_clu, n_neurons, locs = summarize_non_hdf5(p)
    summary.append((folder, subj, date, ntrials, has_clu, n_neurons, tuple(locs)))
    sessions_by_task[folder] += 1
    subjects_by_task[folder].add(subj)
    trials_by_task[folder] += ntrials
    for loc in locs:
        region_counts[str(loc)] += 1

print('DATA_STRUCTURE_FILES', len(summary))
print('TASK_SUMMARY')
for folder in sorted(sessions_by_task):
    sess = sessions_by_task[folder]
    subjs = len(subjects_by_task[folder])
    trials = trials_by_task[folder]
    neurons = sum(x[5] for x in summary if x[0] == folder)
    print(folder, {'sessions': sess, 'subjects': subjs, 'trials': trials, 'neurons': neurons})

ephys = [x for x in summary if x[4]]
print('ALL_SUBJECTS', len({x[1] for x in summary}), sorted({x[1] for x in summary}))
print('ALL_SESSIONS', len(summary))
print('ALL_TRIALS', sum(x[3] for x in summary))
print('EPHYS_SUBJECTS', len({x[1] for x in ephys}), sorted({x[1] for x in ephys}))
print('EPHYS_SESSIONS', len(ephys))
print('EPHYS_TRIALS', sum(x[3] for x in ephys))
print('EPHYS_NEURONS_RAW', sum(x[5] for x in ephys))
print('EPHYS_NEURONS_PER_SESSION_MIN_MED_MAX', min(x[5] for x in ephys), int(np.median([x[5] for x in ephys])), max(x[5] for x in ephys))
print('EPHYS_TRIALS_PER_SESSION_MIN_MED_MAX', min(x[3] for x in ephys), int(np.median([x[3] for x in ephys])), max(x[3] for x in ephys))
print('REGION_COUNTS', dict(region_counts))
print('UNIQUE_REGION_LABELS', sorted(set(region_counts)))
