python3 - <<'PY'
from pathlib import Path
import h5py, numpy as np, scipy.io
root = Path('/app/data/Ephys_Behavior')
files = sorted(root.glob('data_structure_*.mat'))

def autowater_vals_hdf5(p):
    with h5py.File(p,'r') as f:
        arr = f['obj/bp/autowater'][()]
        return np.unique(arr.astype(float).reshape(-1))

def autowater_vals_nonhdf5(p):
    obj = scipy.io.loadmat(str(p), squeeze_me=True, struct_as_record=False)['obj']
    return np.unique(np.asarray(obj.bp.autowater).astype(float).reshape(-1))

both=[]; one=[]
for p in files:
    vals = autowater_vals_hdf5(p) if h5py.is_hdf5(str(p)) else autowater_vals_nonhdf5(p)
    vals = vals[~np.isnan(vals)]
    if set(np.round(vals).astype(int)) == {0,1}:
        both.append(p.name)
    else:
        one.append((p.name, vals.tolist()))
print('both contexts', len(both))
for x in both: print(x)
print('\none context only', len(one))
for x in one: print(x)
